    # Find leftmost non-zero column
    leftmost = None
    for c in range(18):
        if test_input[r][c] != 0:
            leftmost = c
            break

    if leftmost is None:
        continue  # Empty row, stays empty

    # Check if this row already HAS a complete sequence
    # A complete sequence would have LEN_SEQ consecutive non-zeros
    has_complete = False
    for start in range(18 - LEN_SEQ + 1):
        is_complete = True
        for i in range(LEN_SEQ):
            if test_input[r][start + i] == 0:
                is_complete = False
                break
        if is_complete:
            has_complete = True
            break

    if has_complete:
        # Keep row as-is
        for c in range(18):
            output[r][c] = test_input[r][c]
    else:
        # Place full sequence starting at leftmost non-zero column
        for i in range(LEN_SEQ):
            out_col = (leftmost + i) % 18
            output[r][out_col] = seq[i]

